DECLARE
  a public.appointments;
  r text;
BEGIN
  -- 1. Authorize ACTIVE TECHNICIAN in target company
  r := public.operations_actor(p_company_id, p_actor_id, ARRAY['TECHNICIAN']);

  -- 2. Lock appointment
  SELECT * INTO a FROM public.appointments
  WHERE company_id = p_company_id AND id = p_appointment_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'RESOURCE_NOT_FOUND';
  END IF;

  -- 3. Verify appointment type
  IF a.type <> 'INSTALLATION' THEN
    RAISE EXCEPTION 'INVALID_INPUT';
  END IF;

  -- 4. Only the exact assigned ACTIVE TECHNICIAN may accept it
  IF a.assignee_id <> p_actor_id THEN
    RAISE EXCEPTION 'PERMISSION_DENIED';
  END IF;

  -- 5. Idempotent check
  IF a.status = 'ACCEPTED' THEN
    RETURN jsonb_build_object('success', true, 'idempotent', true);
  END IF;

  IF a.status <> 'ASSIGNED' THEN
    RAISE EXCEPTION 'INVALID_STATE_TRANSITION';
  END IF;

  -- 6. Transition
  UPDATE public.appointments
  SET status = 'ACCEPTED',
      updated_at = now()
  WHERE id = a.id;

  -- 7. Audit log
  PERFORM public.operations_audit(
    p_company_id,
    p_actor_id,
    'ACCEPT_INSTALLATION_APPOINTMENT',
    'appointments',
    a.id,
    jsonb_build_object(
      'from_status', 'ASSIGNED',
      'to_status', 'ACCEPTED'
    )
  );

  RETURN jsonb_build_object('success', true, 'idempotent', false);
END;

DECLARE
  a public.appointments;
  v_op public.survey_photo_operations;
  v_token uuid;
BEGIN
  SELECT * INTO a FROM public.appointments WHERE id = p_appointment_id FOR UPDATE;
  IF NOT FOUND OR a.type <> 'SURVEY' OR a.status NOT IN ('ASSIGNED','ACCEPTED','IN_PROGRESS') THEN
    RAISE EXCEPTION 'INVALID_SURVEY_PHOTO_RESOURCE';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.user_profiles p JOIN public.company_members m ON m.user_id = p.id
    WHERE p.id = p_actor_id AND p.status = 'ACTIVE' AND m.status = 'ACTIVE'
      AND m.company_id = a.company_id
      AND (m.role = 'BOSS_ADMIN' OR (m.role = 'TECHNICIAN' AND a.assignee_id = p_actor_id))
  ) THEN RAISE EXCEPTION 'SURVEY_PHOTO_FORBIDDEN'; END IF;

  SELECT * INTO v_op FROM public.survey_photo_operations
  WHERE appointment_id = a.id FOR UPDATE;

  IF FOUND THEN
    IF v_op.expires_at > pg_catalog.now() THEN
      RAISE EXCEPTION 'SURVEY_PHOTO_OPERATION_IN_PROGRESS';
    END IF;
    -- Expired lock: atomically reclaim it with new token and fixed 15-minute lease
    v_token := pg_catalog.gen_random_uuid();
    UPDATE public.survey_photo_operations
    SET token = v_token,
        actor_id = p_actor_id,
        started_at = pg_catalog.now(),
        expires_at = pg_catalog.now() + interval '15 minutes'
    WHERE appointment_id = a.id;
    RETURN v_token;
  END IF;

  v_token := pg_catalog.gen_random_uuid();
  INSERT INTO public.survey_photo_operations(appointment_id, token, actor_id, started_at, expires_at)
  VALUES (a.id, v_token, p_actor_id, pg_catalog.now(), pg_catalog.now() + interval '15 minutes');
  RETURN v_token;
END

DECLARE
    v_order public.orders%ROWTYPE;
    v_current_contract public.contracts%ROWTYPE;
    v_contract_id uuid;
    v_max_revision integer := 0;
    v_next_revision integer;
BEGIN
    -- Advisory lock per (company_id, order_id)
    PERFORM pg_advisory_xact_lock(hashtext(p_company_id::text || ':CONTRACT:' || p_order_id::text));

    SELECT * INTO v_order
    FROM public.orders
    WHERE id = p_order_id AND company_id = p_company_id
    FOR UPDATE;

    IF v_order.id IS NULL THEN
        RAISE EXCEPTION 'RESOURCE_NOT_FOUND: Order not found';
    END IF;

    IF v_order.deposit_status <> 'DEPOSIT_CONFIRMED' THEN
        RAISE EXCEPTION 'DEPOSIT_NOT_CONFIRMED: Cannot generate contract until deposit is confirmed';
    END IF;

    -- Look up current contract for this order
    SELECT * INTO v_current_contract
    FROM public.contracts
    WHERE company_id = p_company_id AND order_id = p_order_id AND is_current
    LIMIT 1;

    IF v_current_contract.id IS NOT NULL THEN
        -- Section 9: Never overwrite SIGNED contracts
        IF v_current_contract.status = 'SIGNED' AND p_force_revision THEN
            RAISE EXCEPTION 'CANNOT_REVISE_SIGNED_CONTRACT: Signed contracts cannot be regenerated or superseded';
        END IF;

        -- If not forcing revision: return existing canonical contract
        IF NOT p_force_revision THEN
            IF v_current_contract.status IN ('GENERATED', 'SENT_TO_CUSTOMER', 'SIGNED') AND v_current_contract.generated_file_ref <> 'CLAIMED' THEN
                RETURN jsonb_build_object(
                    'status', 'ALREADY_EXISTS',
                    'contractId', v_current_contract.id,
                    'revisionNo', v_current_contract.revision_no,
                    'contractStatus', v_current_contract.status,
                    'generatedFileRef', v_current_contract.generated_file_ref
                );
            END IF;

            RETURN jsonb_build_object(
                'status', 'CLAIMED',
                'contractId', v_current_contract.id,
                'revisionNo', v_current_contract.revision_no,
                'orderFinalAmount', v_order.final_amount,
                'customerId', v_order.customer_id
            );
        END IF;

        -- If explicit regeneration requested: previous current becomes SUPERSEDED, is_current = false
        UPDATE public.contracts
        SET is_current = false,
            status = 'SUPERSEDED',
            updated_at = now()
        WHERE id = v_current_contract.id;
    END IF;

    -- Determine next revision number atomically
    SELECT COALESCE(MAX(revision_no), 0) INTO v_max_revision
    FROM public.contracts
    WHERE company_id = p_company_id AND order_id = p_order_id;

    v_next_revision := v_max_revision + 1;

    -- Insert new current contract
    INSERT INTO public.contracts (
        company_id,
        order_id,
        revision_no,
        template_version,
        generated_file_ref,
        signed_file_ref,
        status,
        contract_value,
        is_current
    ) VALUES (
        p_company_id,
        p_order_id,
        v_next_revision,
        'v1',
        'CLAIMED',
        NULL,
        'GENERATED',
        v_order.final_amount,
        true
    )
    RETURNING id INTO v_contract_id;

    RETURN jsonb_build_object(
        'status', 'CLAIMED',
        'contractId', v_contract_id,
        'revisionNo', v_next_revision,
        'orderFinalAmount', v_order.final_amount,
        'customerId', v_order.customer_id
    );
END;

DECLARE
  i public.installations;
  o public.orders;
  a public.appointments;
  r text;
  ref text;
BEGIN
  r := public.operations_actor(p_company_id, p_actor_id, ARRAY['BOSS_ADMIN','TECHNICIAN']);
  SELECT * INTO i FROM public.installations WHERE company_id = p_company_id AND id = p_installation_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'RESOURCE_NOT_FOUND'; END IF;

  SELECT * INTO o FROM public.orders WHERE company_id = p_company_id AND id = i.order_id FOR UPDATE;
  IF NOT FOUND OR o.customer_id <> i.customer_id THEN RAISE EXCEPTION 'RESOURCE_NOT_FOUND'; END IF;

  SELECT * INTO a FROM public.appointments WHERE company_id = p_company_id AND id = i.appointment_id FOR UPDATE;
  IF NOT FOUND OR a.customer_id <> i.customer_id OR a.type <> 'INSTALLATION' THEN RAISE EXCEPTION 'RESOURCE_NOT_FOUND'; END IF;

  IF r = 'TECHNICIAN' AND a.assignee_id <> p_actor_id THEN RAISE EXCEPTION 'PERMISSION_DENIED'; END IF;

  -- Idempotency check: if all are already completed
  IF i.status = 'COMPLETED' AND o.order_status = 'COMPLETED' THEN
    IF a.status <> 'COMPLETED' THEN
      UPDATE public.appointments SET status = 'COMPLETED', updated_at = now() WHERE id = a.id;
    END IF;
    RETURN jsonb_build_object('success', true, 'idempotent', true);
  END IF;

  -- Predecessor checks: installation HANDOVER_PENDING, order in READY_FOR_INSTALL/INSTALLING, appointment in ACCEPTED/IN_PROGRESS
  IF i.status <> 'HANDOVER_PENDING' OR o.order_status NOT IN ('READY_FOR_INSTALL','INSTALLING') OR a.status NOT IN ('ACCEPTED','IN_PROGRESS') THEN
    RAISE EXCEPTION 'INVALID_STATE_TRANSITION';
  END IF;

  -- Mandatory evidence checks
  IF jsonb_typeof(i.photos) <> 'array' OR jsonb_array_length(i.photos) = 0 OR NULLIF(btrim(i.handover_ref), '') IS NULL THEN
    RAISE EXCEPTION 'MISSING_EVIDENCE';
  END IF;

  IF i.photos IS DISTINCT FROM p_verified_photos OR i.handover_ref IS DISTINCT FROM p_verified_handover THEN
    RAISE EXCEPTION 'EVIDENCE_CHANGED';
  END IF;

  FOR ref IN SELECT jsonb_array_elements_text(i.photos) LOOP
    IF NOT public.operations_evidence_ref(p_company_id, i.id, ref, 'photo') THEN
      RAISE EXCEPTION 'INVALID_STORAGE_REF';
    END IF;
  END LOOP;

  IF NOT public.operations_evidence_ref(p_company_id, i.id, i.handover_ref, 'handover') THEN
    RAISE EXCEPTION 'INVALID_STORAGE_REF';
  END IF;

  -- Update all 3 records atomically in one transaction
  UPDATE public.installations SET status = 'COMPLETED', completed_at = now(), updated_at = now() WHERE id = i.id;
  UPDATE public.orders SET order_status = 'COMPLETED', updated_at = now() WHERE id = o.id;
  UPDATE public.appointments SET status = 'COMPLETED', updated_at = now() WHERE id = a.id;

  PERFORM public.operations_audit(
    p_company_id,
    p_actor_id,
    'COMPLETE_INSTALLATION_AND_HANDOVER',
    'installations',
    i.id,
    jsonb_build_object('order_id', o.id, 'appointment_id', a.id)
  );

  INSERT INTO public.operations_outbox (company_id, order_id, event_type, payload)
  VALUES (p_company_id, o.id, 'ORDER_COMPLETED', jsonb_build_object('installation_id', i.id, 'completed_at', now()))
  ON CONFLICT (company_id, order_id, event_type) DO NOTHING;

  RETURN jsonb_build_object('success', true, 'idempotent', false);
END;

DECLARE
  a public.appointments;
  s public.surveys;
  v_now timestamptz := pg_catalog.now();
  m jsonb;
  c jsonb;
  v_photos jsonb := '[]'::jsonb;
  v_slot text;
  v_path text;
  v_key text;
  v_min numeric;
  v_max numeric;
BEGIN
  SELECT * INTO a FROM public.appointments WHERE id = p_appointment_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'APPOINTMENT_NOT_FOUND'; END IF;
  IF a.type <> 'SURVEY' THEN RAISE EXCEPTION 'APPOINTMENT_TYPE_NOT_SURVEY'; END IF;
  IF p_completed_by IS NULL OR a.assignee_id IS DISTINCT FROM p_completed_by THEN
    RAISE EXCEPTION 'INVALID_COMPLETED_BY';
  END IF;
  -- Lock actor records too: deactivation must serialize with this completion transaction.
  PERFORM 1 FROM public.user_profiles p JOIN public.company_members cm ON cm.user_id = p.id
    WHERE p.id = p_completed_by AND p.status = 'ACTIVE'
      AND cm.company_id = a.company_id AND cm.status = 'ACTIVE' AND cm.role = 'TECHNICIAN'
    FOR SHARE OF p, cm;
  IF NOT FOUND THEN RAISE EXCEPTION 'INVALID_COMPLETED_BY'; END IF;

  SELECT * INTO s FROM public.surveys WHERE appointment_id = a.id;
  IF a.status = 'COMPLETED' THEN
    IF s.id IS NULL OR s.company_id <> a.company_id OR s.customer_id <> a.customer_id
       OR s.completed_by IS DISTINCT FROM p_completed_by THEN
      RAISE EXCEPTION 'SURVEY_COMPLETION_INCONSISTENT';
    END IF;
    RETURN pg_catalog.jsonb_build_object('id', s.id, 'isExisting', true);
  END IF;
  IF a.status NOT IN ('ACCEPTED','IN_PROGRESS') THEN RAISE EXCEPTION 'INVALID_PREDECESSOR_STATE'; END IF;
  IF s.id IS NOT NULL THEN RAISE EXCEPTION 'SURVEY_ALREADY_EXISTS'; END IF;
  -- A live (unexpired) photo operation blocks completion
  IF EXISTS (
    SELECT 1 FROM public.survey_photo_operations
    WHERE appointment_id = a.id AND expires_at > pg_catalog.now()
  ) THEN
    RAISE EXCEPTION 'SURVEY_PHOTO_OPERATION_IN_PROGRESS';
  END IF;

  m := p_survey_payload->'measurements';
  c := (p_survey_payload->>'site_condition')::jsonb;
  IF pg_catalog.jsonb_typeof(m) IS DISTINCT FROM 'object' OR pg_catalog.jsonb_typeof(c) IS DISTINCT FROM 'object' THEN
    RAISE EXCEPTION 'INVALID_SURVEY_TECHNICAL_INPUT';
  END IF;
  FOR v_key, v_min, v_max IN VALUES ('clear_width_mm',500,15000),
      ('barrier_height_mm',100,3000),('anticipated_flood_height_mm',100,3000) LOOP
    IF pg_catalog.jsonb_typeof(m->v_key) IS DISTINCT FROM 'number' THEN RAISE EXCEPTION 'INVALID_SURVEY_MEASUREMENT'; END IF;
    IF (m->>v_key)::numeric NOT BETWEEN v_min AND v_max
       OR pg_catalog.trunc((m->>v_key)::numeric) <> (m->>v_key)::numeric THEN
      RAISE EXCEPTION 'INVALID_SURVEY_MEASUREMENT';
    END IF;
  END LOOP;
  IF m ? 'step_height_mm' AND (pg_catalog.jsonb_typeof(m->'step_height_mm') <> 'number'
      OR (m->>'step_height_mm')::numeric NOT BETWEEN 0 AND 1000) THEN
    RAISE EXCEPTION 'INVALID_SURVEY_MEASUREMENT';
  END IF;
  IF NOT coalesce(m->>'gate_type' IN ('REMOVABLE_PANEL','AUTOMATIC_HYDRAULIC','ROLL_UP_CANVAS','SWING_GATE'),false)
    OR NOT coalesce(m->>'mounting_method' IN ('INSIDE_JAMB','OUTSIDE_FACE','INSIDE_FACE'),false)
    OR NOT coalesce(c->>'wall_material' IN ('SOLID_BRICK','HOLLOW_BRICK','CONCRETE','STEEL_FRAME','ALUMINUM_GLASS','STONE_TILES'),false)
    OR NOT coalesce(c->>'floor_material' IN ('CONCRETE_SMOOTH','TILES','NATURAL_STONE','ROUGH_CEMENT','PAVING_BRICK'),false)
    OR NOT coalesce(c->>'floor_evenness' IN ('FLAT','SLIGHTLY_UNEVEN','HIGHLY_UNEVEN'),false)
    OR NOT coalesce(c->>'slope_grade' IN ('SLOPING_OUT','LEVEL','SLOPING_IN'),false) THEN
    RAISE EXCEPTION 'INVALID_SURVEY_TECHNICAL_INPUT';
  END IF;
  IF pg_catalog.length(coalesce(p_survey_payload->>'notes','')) > 1000
    OR pg_catalog.length(coalesce(c->>'notes','')) > 1000 OR pg_catalog.length(coalesce(c->>'specialRequirements','')) > 1000 THEN
    RAISE EXCEPTION 'INVALID_SURVEY_NOTES';
  END IF;

  -- Server-owned paths only. Ignore payload.photos, Company, Customer, completed_by and completed_at.
  FOREACH v_slot IN ARRAY ARRAY['OVERVIEW','BOTTOM_LEFT','BOTTOM_RIGHT','OBSTACLE','SLOPE_DETAIL','ADDITIONAL'] LOOP
    v_path := a.company_id::text || '/' || a.customer_id::text || '/' || a.id::text || '/' || v_slot || '.jpg';
    IF EXISTS (SELECT 1 FROM storage.objects WHERE bucket_id = 'survey-photos' AND name = v_path) THEN
      v_photos := v_photos || pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object('slot',v_slot,'objectPath',v_path,
        'uploadedAt',v_now,'slotLabel',v_slot,'isMandatory',v_slot IN ('OVERVIEW','BOTTOM_LEFT','BOTTOM_RIGHT')));
    ELSIF v_slot IN ('OVERVIEW','BOTTOM_LEFT','BOTTOM_RIGHT') THEN
      RAISE EXCEPTION 'MISSING_MANDATORY_SURVEY_PHOTO';
    END IF;
  END LOOP;

  INSERT INTO public.surveys(company_id,customer_id,appointment_id,completed_by,measurements,photos,
    site_condition,notes,completed_at,created_at,updated_at)
  VALUES (a.company_id,a.customer_id,a.id,p_completed_by,m,v_photos,c::text,p_survey_payload->>'notes',v_now,v_now,v_now)
  RETURNING * INTO s;
  PERFORM pg_catalog.set_config('app.survey_completion', a.id::text, true);
  UPDATE public.appointments SET status = 'COMPLETED', updated_at = v_now
    WHERE id = a.id AND status IN ('ACCEPTED','IN_PROGRESS');
  IF NOT FOUND THEN RAISE EXCEPTION 'SURVEY_APPOINTMENT_UPDATE_FAILED'; END IF;
  PERFORM pg_catalog.set_config('app.survey_completion', '', true);
  RETURN pg_catalog.jsonb_build_object('id',s.id,'isExisting',false);
END

DECLARE
  p public.production_orders;
  o public.orders;
  i public.installations;
  a public.appointments;
  v_address text;
  v_canonical_crew jsonb;
  v_existing_crew jsonb;
BEGIN
  -- 1. Authorize ACTIVE BOSS_ADMIN in the target company
  PERFORM public.operations_actor(p_company_id, p_actor_id, ARRAY['BOSS_ADMIN']);

  -- 2. Validate target technician: ACTIVE UserProfile, ACTIVE membership, role TECHNICIAN, same company
  PERFORM public.operations_actor(p_company_id, p_technician_id, ARRAY['TECHNICIAN']);

  -- 3. Input validation
  IF p_start_time IS NULL THEN
    RAISE EXCEPTION 'INVALID_INPUT: Thời gian bắt đầu lắp đặt không được để trống.';
  END IF;

  v_address := NULLIF(btrim(p_address), '');
  IF v_address IS NULL THEN
    RAISE EXCEPTION 'INVALID_INPUT: Địa chỉ lắp đặt không được để trống.';
  END IF;

  IF p_crew IS NULL OR jsonb_typeof(p_crew) <> 'array' OR jsonb_array_length(p_crew) = 0 THEN
    RAISE EXCEPTION 'INVALID_INPUT: Danh sách đội thợ (crew) phải có ít nhất 1 người.';
  END IF;

  IF EXISTS (SELECT 1 FROM jsonb_array_elements_text(p_crew) elem WHERE btrim(elem) = '') THEN
    RAISE EXCEPTION 'INVALID_INPUT: Tên thành viên đội thợ không được để trống.';
  END IF;

  -- Canonicalize crew: trim each member and sort alphabetically for deterministic comparison
  SELECT COALESCE(
    jsonb_agg(btrim(elem) ORDER BY btrim(elem)),
    '[]'::jsonb
  )
  INTO v_canonical_crew
  FROM jsonb_array_elements_text(p_crew) AS elem;

  -- 4. Lock ProductionOrder and Order (match QC lock order: production_orders -> orders)
  SELECT * INTO p FROM public.production_orders
  WHERE company_id = p_company_id AND order_id = p_order_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'RESOURCE_NOT_FOUND';
  END IF;

  SELECT * INTO o FROM public.orders
  WHERE company_id = p_company_id AND id = p_order_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'RESOURCE_NOT_FOUND';
  END IF;

  -- 5. Idempotency & Concurrency: Check if an installation already exists for this order
  SELECT * INTO i FROM public.installations
  WHERE company_id = p_company_id AND order_id = o.id
  FOR UPDATE;

  IF FOUND THEN
    SELECT * INTO a FROM public.appointments
    WHERE company_id = p_company_id AND id = i.appointment_id
    FOR UPDATE;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'RESOURCE_NOT_FOUND';
    END IF;

    -- Canonicalize existing crew for comparison
    SELECT COALESCE(
      jsonb_agg(btrim(elem) ORDER BY btrim(elem)),
      '[]'::jsonb
    )
    INTO v_existing_crew
    FROM jsonb_array_elements_text(i.crew) AS elem;

    -- Strict logical payload mismatch check
    IF a.assignee_id <> p_technician_id
       OR a.start_time <> p_start_time
       OR btrim(a.address) <> v_address
       OR v_existing_crew <> v_canonical_crew THEN
      RAISE EXCEPTION 'INSTALLATION_SCHEDULE_ALREADY_EXISTS_WITH_DIFFERENT_PAYLOAD';
    END IF;

    RETURN jsonb_build_object(
      'success', true,
      'idempotent', true,
      'installation', to_jsonb(i),
      'appointment', to_jsonb(a)
    );
  END IF;

  -- 6. Confirm states: ProductionOrder READY_FOR_DISPATCH & PASSED, Order READY_FOR_INSTALL
  IF p.status <> 'READY_FOR_DISPATCH' OR p.qc_status <> 'PASSED' OR o.order_status <> 'READY_FOR_INSTALL' THEN
    RAISE EXCEPTION 'INVALID_STATE_TRANSITION';
  END IF;

  -- 7. Create Appointment: type = INSTALLATION, status = ASSIGNED
  INSERT INTO public.appointments (
    company_id,
    customer_id,
    type,
    start_time,
    assignee_id,
    address,
    status
  ) VALUES (
    p_company_id,
    o.customer_id,
    'INSTALLATION',
    p_start_time,
    p_technician_id,
    v_address,
    'ASSIGNED'
  ) RETURNING * INTO a;

  -- 8. Create Installation: status = SCHEDULED, storing canonical crew
  INSERT INTO public.installations (
    company_id,
    customer_id,
    order_id,
    appointment_id,
    crew,
    status
  ) VALUES (
    p_company_id,
    o.customer_id,
    o.id,
    a.id,
    v_canonical_crew,
    'SCHEDULED'
  ) RETURNING * INTO i;

  -- 9. Append-only audit record
  PERFORM public.operations_audit(
    p_company_id,
    p_actor_id,
    'SCHEDULE_INSTALLATION',
    'installations',
    i.id,
    jsonb_build_object(
      'order_id', o.id,
      'appointment_id', a.id,
      'technician_id', p_technician_id,
      'start_time', p_start_time
    )
  );

  -- 10. Commit all-or-nothing
  RETURN jsonb_build_object(
    'success', true,
    'idempotent', false,
    'installation', to_jsonb(i),
    'appointment', to_jsonb(a)
  );
END;

DECLARE
    v_calc public.price_calculations%ROWTYPE;
    v_existing_order public.orders%ROWTYPE;
    v_order_id uuid;
    v_order_code text;
    v_current_customer_stage text;
BEGIN
    -- Validate actor user ID is provided (no arbitrary or NULL human actor allowed)
    IF p_actor_user_id IS NULL THEN
        RAISE EXCEPTION 'ACTOR_REQUIRED: Actor user ID must be provided';
    END IF;

    -- Validate actor is ACTIVE and has allowed commercial role (BOSS_ADMIN or SALE) in company
    IF NOT EXISTS (
        SELECT 1 FROM public.company_members cm
        JOIN public.user_profiles up ON cm.user_id = up.id
        WHERE cm.company_id = p_company_id
          AND cm.user_id = p_actor_user_id
          AND cm.status = 'ACTIVE'
          AND up.status = 'ACTIVE'
          AND cm.role IN ('BOSS_ADMIN', 'SALE')
    ) THEN
        RAISE EXCEPTION 'UNAUTHORIZED_ROLE: Actor must be active BOSS_ADMIN or SALE in company';
    END IF;

    -- Validate calculation exists and belongs to company & customer (acquires authoritative lock)
    SELECT * INTO v_calc
    FROM public.price_calculations
    WHERE id = p_price_calculation_id AND company_id = p_company_id AND customer_id = p_customer_id
    FOR UPDATE;

    IF v_calc.id IS NULL THEN
        RAISE EXCEPTION 'RESOURCE_NOT_FOUND: Price calculation not found';
    END IF;

    IF v_calc.status <> 'CALCULATED' OR v_calc.amount IS NULL THEN
        RAISE EXCEPTION 'INVALID_PRICE_CALCULATION: Cannot create order from calculation status %', v_calc.status;
    END IF;

    -- Idempotent check: After acquiring lock, re-check for an existing canonical Order
    SELECT * INTO v_existing_order
    FROM public.orders
    WHERE company_id = p_company_id AND price_calculation_id = p_price_calculation_id;

    IF v_existing_order.id IS NOT NULL THEN
        RETURN jsonb_build_object(
            'status', 'ALREADY_EXISTS',
            'orderId', v_existing_order.id,
            'orderCode', v_existing_order.order_code,
            'finalAmount', v_existing_order.final_amount,
            'depositStatus', v_existing_order.deposit_status,
            'orderStatus', v_existing_order.order_status,
            'paymentReference', v_existing_order.payment_reference
        );
    END IF;

    -- Check customer stage
    SELECT stage INTO v_current_customer_stage
    FROM public.customers
    WHERE id = p_customer_id AND company_id = p_company_id
    FOR UPDATE;

    IF v_current_customer_stage IS NULL THEN
        RAISE EXCEPTION 'RESOURCE_NOT_FOUND: Customer not found';
    END IF;

    -- Generate unique order code
    v_order_code := public.generate_order_code();

    -- Insert Order (server authoritative final_amount = calculation.amount)
    INSERT INTO public.orders (
        company_id,
        customer_id,
        order_code,
        payment_reference,
        price_calculation_id,
        deposit_status,
        order_status,
        final_amount
    ) VALUES (
        p_company_id,
        p_customer_id,
        v_order_code,
        p_payment_reference,
        v_calc.id,
        'PENDING',
        'DRAFT',
        v_calc.amount
    ) RETURNING id INTO v_order_id;

    -- Initialize Finance Summary
    INSERT INTO public.finance_summaries (
        order_id,
        company_id,
        contract_value,
        collected_amount,
        receivable_amount,
        completed_revenue
    ) VALUES (
        v_order_id,
        p_company_id,
        v_calc.amount,
        0,
        v_calc.amount,
        0
    );

    -- Update Customer stage to ORDER_CREATED only if customer is in earlier stage
    IF v_current_customer_stage IN ('LEAD_NEW', 'LEAD', 'SURVEY_SCHEDULED', 'SURVEY_COMPLETED', 'PRICE_CALCULATED', 'PRICE_OFFERED', 'NEGOTIATING') THEN
        UPDATE public.customers
        SET stage = 'ORDER_CREATED', updated_at = now()
        WHERE id = p_customer_id;

        INSERT INTO public.customer_stage_histories (
            company_id, customer_id, from_stage, to_stage, actor_type, changed_by_user_id, reason
        ) VALUES (
            p_company_id, p_customer_id, v_current_customer_stage, 'ORDER_CREATED', 'USER', p_actor_user_id, 'Order created from calculation'
        );
    END IF;

    -- Mandatory audit log inserted atomically (failure rolls back mutation)
    INSERT INTO public.audit_logs (
        company_id, user_id, action, resource_type, resource_id, customer_id, result, metadata
    ) VALUES (
        p_company_id,
        p_actor_user_id,
        'ORDER_CREATED',
        'orders',
        v_order_id,
        p_customer_id,
        'SUCCESS',
        jsonb_build_object(
            'order_code', v_order_code,
            'price_calculation_id', v_calc.id,
            'final_amount', v_calc.amount
        )
    );

    RETURN jsonb_build_object(
        'status', 'CREATED',
        'orderId', v_order_id,
        'orderCode', v_order_code,
        'finalAmount', v_calc.amount,
        'depositStatus', 'PENDING',
        'orderStatus', 'DRAFT',
        'paymentReference', p_payment_reference
    );
END;

DECLARE
  o public.orders;
  c public.contracts;
  p public.production_orders;
  pc public.price_calculations;
  pp public.pricing_policies;
  s public.surveys;
  v_canonical_specs jsonb;
  v_canonical_materials jsonb;
  v_final_specs jsonb;
  v_final_materials jsonb;
  v_canonical_dim text;
  v_cw_mm numeric;
  v_bh_mm numeric;
  v_w numeric;
  v_h numeric;
  v_key text;
BEGIN
  -- 1. Validate actor: BOSS_ADMIN only
  PERFORM public.operations_actor(p_company_id, p_actor_id, ARRAY['BOSS_ADMIN']);

  -- 2. Reject empty or null client specs / materials
  IF p_specs IS NULL OR jsonb_typeof(p_specs) = 'null' OR p_specs = '{}'::jsonb
     OR p_materials IS NULL OR jsonb_typeof(p_materials) = 'null' OR p_materials = '{}'::jsonb THEN
    RAISE EXCEPTION 'INVALID_TECHNICAL_INPUT';
  END IF;

  -- 3. Reject arbitrary client-only specs keys (must be domain-recognized technical fields or notes)
  FOR v_key IN SELECT jsonb_object_keys(p_specs) LOOP
    IF v_key NOT IN (
      'dimensions', 'clear_width_mm', 'barrier_height_mm', 'width', 'height',
      'gate_type', 'mounting_method', 'thickness_mm', 'tolerance_mm', 'notes'
    ) THEN
      RAISE EXCEPTION 'INVALID_TECHNICAL_INPUT';
    END IF;
  END LOOP;

  -- 4. Reject arbitrary client-only materials keys (must be domain-recognized material specifications)
  FOR v_key IN SELECT jsonb_object_keys(p_materials) LOOP
    IF v_key NOT IN (
      'aluminum', 'inox', 'steel', 'gasket', 'seal', 'profile', 'panel', 'frame', 'hardware', 'fasteners'
    ) THEN
      RAISE EXCEPTION 'INVALID_TECHNICAL_INPUT';
    END IF;
    -- Material value must not be empty or blank string
    IF NULLIF(btrim(p_materials->>v_key), '') IS NULL THEN
      RAISE EXCEPTION 'INVALID_TECHNICAL_INPUT';
    END IF;
  END LOOP;

  -- 5. Fetch order with row lock
  SELECT * INTO o FROM public.orders WHERE company_id = p_company_id AND id = p_order_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'RESOURCE_NOT_FOUND';
  END IF;

  IF o.order_status NOT IN ('CONTRACT_SIGNED', 'DEPOSIT_CONFIRMED') THEN
    RAISE EXCEPTION 'INVALID_STATE_TRANSITION';
  END IF;

  -- 6. Contract gate: valid signed contract required
  SELECT * INTO c FROM public.contracts
  WHERE company_id = p_company_id AND order_id = o.id AND is_current FOR UPDATE;
  IF NOT FOUND OR c.status <> 'SIGNED' OR NULLIF(btrim(c.signed_file_ref), '') IS NULL THEN
    RAISE EXCEPTION 'CONTRACT_NOT_SIGNED';
  END IF;

  -- 7. Prevent duplicate production order
  IF EXISTS(SELECT 1 FROM public.production_orders WHERE order_id = o.id) THEN
    RAISE EXCEPTION 'PRODUCTION_ALREADY_EXISTS';
  END IF;

  -- 8. Fetch authoritative price calculation record
  SELECT * INTO pc FROM public.price_calculations
  WHERE id = o.price_calculation_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'RESOURCE_NOT_FOUND';
  END IF;

  -- Multi-tenant and customer boundary validation
  IF pc.company_id <> p_company_id THEN
    RAISE EXCEPTION 'PERMISSION_DENIED';
  END IF;
  IF pc.customer_id <> o.customer_id THEN
    RAISE EXCEPTION 'MISMATCHED_CUSTOMER_REFERENCE';
  END IF;

  -- Check calculation status: fail closed if input missing or incomplete
  IF pc.status = 'NEED_INFO' THEN
    RAISE EXCEPTION 'Cannot release to production: missing canonical dimensions or barrier type'
      USING ERRCODE = 'NEED_INFO';
  END IF;
  IF pc.status <> 'CALCULATED' THEN
    RAISE EXCEPTION 'INVALID_TECHNICAL_INPUT';
  END IF;
  IF pc.input_data IS NULL OR pc.input_data = '{}'::jsonb THEN
    RAISE EXCEPTION 'INVALID_TECHNICAL_INPUT';
  END IF;

  -- 9. Fetch and validate authoritative pricing policy
  SELECT * INTO pp FROM public.pricing_policies
  WHERE id = pc.pricing_policy_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'RESOURCE_NOT_FOUND';
  END IF;
  IF pp.company_id <> p_company_id THEN
    RAISE EXCEPTION 'PERMISSION_DENIED';
  END IF;

  -- 10. Validate survey if bound to calculation
  IF pc.survey_id IS NOT NULL THEN
    SELECT * INTO s FROM public.surveys
    WHERE id = pc.survey_id FOR UPDATE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'RESOURCE_NOT_FOUND';
    END IF;
    IF s.company_id <> p_company_id THEN
      RAISE EXCEPTION 'PERMISSION_DENIED';
    END IF;
    IF s.customer_id <> o.customer_id THEN
      RAISE EXCEPTION 'MISMATCHED_CUSTOMER_REFERENCE';
    END IF;
    IF s.measurements IS NULL OR s.measurements = '{}'::jsonb THEN
      RAISE EXCEPTION 'INVALID_TECHNICAL_INPUT';
    END IF;
  END IF;

  -- 11. Derive authoritative canonical materials from persisted records
  IF s.id IS NOT NULL AND jsonb_typeof(s.measurements->'materials') = 'object' AND s.measurements->'materials' <> '{}'::jsonb THEN
    v_canonical_materials := s.measurements->'materials';
  ELSIF jsonb_typeof(pc.input_data->'materials') = 'object' AND pc.input_data->'materials' <> '{}'::jsonb THEN
    v_canonical_materials := pc.input_data->'materials';
  ELSIF jsonb_typeof(pp.conditions->'materials') = 'object' AND pp.conditions->'materials' <> '{}'::jsonb THEN
    v_canonical_materials := pp.conditions->'materials';
  ELSIF jsonb_typeof(pp.conditions->'standard_materials') = 'object' AND pp.conditions->'standard_materials' <> '{}'::jsonb THEN
    v_canonical_materials := pp.conditions->'standard_materials';
  ELSIF jsonb_typeof(pp.price_rules->'materials') = 'object' AND pp.price_rules->'materials' <> '{}'::jsonb THEN
    v_canonical_materials := pp.price_rules->'materials';
  ELSIF jsonb_typeof(pp.price_rules->'standard_materials') = 'object' AND pp.price_rules->'standard_materials' <> '{}'::jsonb THEN
    v_canonical_materials := pp.price_rules->'standard_materials';
  ELSE
    v_canonical_materials := NULL;
  END IF;

  -- Fail-closed if authoritative materials are missing
  IF v_canonical_materials IS NULL OR jsonb_typeof(v_canonical_materials) = 'null' OR v_canonical_materials = '{}'::jsonb THEN
    RAISE EXCEPTION 'Cannot release to production: canonical materials specification is missing'
      USING ERRCODE = 'INVALID_TECHNICAL_INPUT';
  END IF;

  -- Detect and reject material tampering / client forgery
  FOR v_key IN SELECT jsonb_object_keys(p_materials) LOOP
    IF v_canonical_materials ? v_key THEN
      IF (p_materials->>v_key) <> (v_canonical_materials->>v_key) THEN
        RAISE EXCEPTION 'Production order material specification cannot contradict canonical policy/survey materials'
          USING ERRCODE = 'INVALID_TECHNICAL_INPUT';
      END IF;
    END IF;
  END LOOP;

  -- Client materials are NOT authoritative; canonical materials are strictly persisted
  v_final_materials := v_canonical_materials;

  -- 12. Derive authoritative canonical specifications (server-authoritative; client cannot override)
  IF s.id IS NOT NULL THEN
    v_cw_mm := NULLIF(s.measurements->>'clear_width_mm', '')::numeric;
    v_bh_mm := NULLIF(s.measurements->>'barrier_height_mm', '')::numeric;
    IF v_cw_mm IS NULL OR v_bh_mm IS NULL OR v_cw_mm <= 0 OR v_bh_mm <= 0 THEN
      RAISE EXCEPTION 'Cannot release to production: missing canonical dimensions or barrier type'
        USING ERRCODE = 'NEED_INFO';
    END IF;
    v_canonical_dim := v_cw_mm::text || 'x' || v_bh_mm::text || 'mm';
    v_canonical_specs := jsonb_build_object(
      'dimensions', v_canonical_dim,
      'canonical_dimensions', v_canonical_dim,
      'canonical_source', 'SURVEY',
      'calculation_id', pc.id,
      'survey_id', s.id,
      'clear_width_mm', v_cw_mm,
      'barrier_height_mm', v_bh_mm
    );
    IF s.measurements ? 'gate_type' AND NULLIF(btrim(s.measurements->>'gate_type'), '') IS NOT NULL THEN
      v_canonical_specs := v_canonical_specs || jsonb_build_object('gate_type', s.measurements->>'gate_type');
    ELSIF pc.input_data ? 'gate_type' AND NULLIF(btrim(pc.input_data->>'gate_type'), '') IS NOT NULL THEN
      v_canonical_specs := v_canonical_specs || jsonb_build_object('gate_type', pc.input_data->>'gate_type');
    END IF;
    IF s.measurements ? 'mounting_method' AND NULLIF(btrim(s.measurements->>'mounting_method'), '') IS NOT NULL THEN
      v_canonical_specs := v_canonical_specs || jsonb_build_object('mounting_method', s.measurements->>'mounting_method');
    ELSIF pc.input_data ? 'mounting_method' AND NULLIF(btrim(pc.input_data->>'mounting_method'), '') IS NOT NULL THEN
      v_canonical_specs := v_canonical_specs || jsonb_build_object('mounting_method', pc.input_data->>'mounting_method');
    END IF;
    -- Canonical thickness from survey -> calculation -> policy
    IF s.measurements ? 'thickness_mm' AND NULLIF(btrim(s.measurements->>'thickness_mm'), '') IS NOT NULL THEN
      v_canonical_specs := v_canonical_specs || jsonb_build_object('thickness_mm', (s.measurements->>'thickness_mm')::numeric);
    ELSIF pc.input_data ? 'thickness_mm' AND NULLIF(btrim(pc.input_data->>'thickness_mm'), '') IS NOT NULL THEN
      v_canonical_specs := v_canonical_specs || jsonb_build_object('thickness_mm', (pc.input_data->>'thickness_mm')::numeric);
    ELSIF pp.conditions ? 'thickness_mm' AND NULLIF(btrim(pp.conditions->>'thickness_mm'), '') IS NOT NULL THEN
      v_canonical_specs := v_canonical_specs || jsonb_build_object('thickness_mm', (pp.conditions->>'thickness_mm')::numeric);
    END IF;
    -- Canonical tolerance from survey -> calculation -> policy
    IF s.measurements ? 'tolerance_mm' AND NULLIF(btrim(s.measurements->>'tolerance_mm'), '') IS NOT NULL THEN
      v_canonical_specs := v_canonical_specs || jsonb_build_object('tolerance_mm', (s.measurements->>'tolerance_mm')::numeric);
    ELSIF pc.input_data ? 'tolerance_mm' AND NULLIF(btrim(pc.input_data->>'tolerance_mm'), '') IS NOT NULL THEN
      v_canonical_specs := v_canonical_specs || jsonb_build_object('tolerance_mm', (pc.input_data->>'tolerance_mm')::numeric);
    ELSIF pp.conditions ? 'tolerance_mm' AND NULLIF(btrim(pp.conditions->>'tolerance_mm'), '') IS NOT NULL THEN
      v_canonical_specs := v_canonical_specs || jsonb_build_object('tolerance_mm', (pp.conditions->>'tolerance_mm')::numeric);
    END IF;
  ELSE
    v_w := NULLIF(pc.input_data->>'width', '')::numeric;
    v_h := NULLIF(pc.input_data->>'height', '')::numeric;
    v_cw_mm := NULLIF(pc.input_data->>'clear_width_mm', '')::numeric;
    v_bh_mm := NULLIF(pc.input_data->>'barrier_height_mm', '')::numeric;

    IF v_w IS NOT NULL AND v_h IS NOT NULL AND v_w > 0 AND v_h > 0 THEN
      v_canonical_dim := (round(v_w * 100)::text || 'x' || round(v_h * 100)::text || 'cm');
      v_canonical_specs := jsonb_build_object(
        'dimensions', v_canonical_dim,
        'canonical_dimensions', v_canonical_dim,
        'canonical_source', 'PRICE_CALCULATION',
        'calculation_id', pc.id,
        'width', v_w,
        'height', v_h
      );
    ELSIF v_cw_mm IS NOT NULL AND v_bh_mm IS NOT NULL AND v_cw_mm > 0 AND v_bh_mm > 0 THEN
      v_canonical_dim := (v_cw_mm::text || 'x' || v_bh_mm::text || 'mm');
      v_canonical_specs := jsonb_build_object(
        'dimensions', v_canonical_dim,
        'canonical_dimensions', v_canonical_dim,
        'canonical_source', 'PRICE_CALCULATION',
        'calculation_id', pc.id,
        'clear_width_mm', v_cw_mm,
        'barrier_height_mm', v_bh_mm
      );
    ELSIF pc.input_data ? 'dimensions' AND NULLIF(btrim(pc.input_data->>'dimensions'), '') IS NOT NULL THEN
      v_canonical_dim := pc.input_data->>'dimensions';
      v_canonical_specs := jsonb_build_object(
        'dimensions', v_canonical_dim,
        'canonical_dimensions', v_canonical_dim,
        'canonical_source', 'PRICE_CALCULATION',
        'calculation_id', pc.id
      );
    ELSE
      -- Incomplete or missing canonical technical input: fail closed
      RAISE EXCEPTION 'Cannot release to production: missing canonical dimensions or barrier type'
        USING ERRCODE = 'NEED_INFO';
    END IF;

    IF pc.input_data ? 'gate_type' AND NULLIF(btrim(pc.input_data->>'gate_type'), '') IS NOT NULL THEN
      v_canonical_specs := v_canonical_specs || jsonb_build_object('gate_type', pc.input_data->>'gate_type');
    END IF;
    IF pc.input_data ? 'mounting_method' AND NULLIF(btrim(pc.input_data->>'mounting_method'), '') IS NOT NULL THEN
      v_canonical_specs := v_canonical_specs || jsonb_build_object('mounting_method', pc.input_data->>'mounting_method');
    END IF;
    -- Canonical thickness from calculation -> policy
    IF pc.input_data ? 'thickness_mm' AND NULLIF(btrim(pc.input_data->>'thickness_mm'), '') IS NOT NULL THEN
      v_canonical_specs := v_canonical_specs || jsonb_build_object('thickness_mm', (pc.input_data->>'thickness_mm')::numeric);
    ELSIF pp.conditions ? 'thickness_mm' AND NULLIF(btrim(pp.conditions->>'thickness_mm'), '') IS NOT NULL THEN
      v_canonical_specs := v_canonical_specs || jsonb_build_object('thickness_mm', (pp.conditions->>'thickness_mm')::numeric);
    END IF;
    -- Canonical tolerance from calculation -> policy
    IF pc.input_data ? 'tolerance_mm' AND NULLIF(btrim(pc.input_data->>'tolerance_mm'), '') IS NOT NULL THEN
      v_canonical_specs := v_canonical_specs || jsonb_build_object('tolerance_mm', (pc.input_data->>'tolerance_mm')::numeric);
    ELSIF pp.conditions ? 'tolerance_mm' AND NULLIF(btrim(pp.conditions->>'tolerance_mm'), '') IS NOT NULL THEN
      v_canonical_specs := v_canonical_specs || jsonb_build_object('tolerance_mm', (pp.conditions->>'tolerance_mm')::numeric);
    END IF;
  END IF;

  -- Technical specifications are strictly server-authoritative.
  -- Every technical field must come from an authoritative persisted source.
  -- Client cannot inject or override technical facts (dimensions, thickness_mm, tolerance_mm, width, height, gate_type, mounting_method).
  -- Only non-technical operational note is accepted from client input (bounded to 1000 characters).
  v_final_specs := v_canonical_specs;
  IF p_specs ? 'notes' AND NULLIF(btrim(p_specs->>'notes'), '') IS NOT NULL THEN
    v_final_specs := v_final_specs || jsonb_build_object('notes', left(btrim(p_specs->>'notes'), 1000));
  END IF;

  -- 12. Insert production order
  INSERT INTO public.production_orders(
    company_id,
    order_id,
    specs,
    materials,
    status,
    deadline,
    qc_status
  ) VALUES (
    p_company_id,
    o.id,
    v_final_specs,
    v_final_materials,
    'RELEASED_TO_FACTORY',
    p_deadline,
    'PENDING'
  ) RETURNING * INTO p;

  -- 13. Advance order status
  UPDATE public.orders SET order_status = 'IN_PRODUCTION', updated_at = now() WHERE id = o.id;

  -- 14. Audit log
  PERFORM public.operations_audit(
    p_company_id,
    p_actor_id,
    'CREATE_PRODUCTION_ORDER',
    'production_orders',
    p.id,
    jsonb_build_object('order_id', o.id)
  );

  RETURN to_jsonb(p);
END;

DECLARE
  v_role text;
  v_cust public.customers;
  v_order public.orders;
  v_inst public.installations;
  v_derived_inst_id uuid := NULL;
  v_ticket public.warranty_tickets;
  v_existing_id uuid;
BEGIN
  -- 1. Validate actor: BOSS_ADMIN or SALE required, active membership and active user profile
  v_role := public.operations_actor(p_company_id, p_actor_id, ARRAY['BOSS_ADMIN', 'SALE']);

  -- 2. Validate issue description
  IF NULLIF(btrim(p_issue), '') IS NULL THEN
    RAISE EXCEPTION 'INVALID_INPUT';
  END IF;

  -- 3. Check idempotency if key provided
  IF p_idempotency_key IS NOT NULL AND btrim(p_idempotency_key) <> '' THEN
    SELECT resource_id INTO v_existing_id
    FROM public.audit_logs
    WHERE company_id = p_company_id
      AND action = 'CREATE_WARRANTY_TICKET'
      AND metadata->>'idempotency_key' = p_idempotency_key
    LIMIT 1;

    IF v_existing_id IS NOT NULL THEN
      SELECT * INTO v_ticket FROM public.warranty_tickets
      WHERE id = v_existing_id AND company_id = p_company_id;
      IF FOUND THEN
        RETURN to_jsonb(v_ticket);
      END IF;
    END IF;
  END IF;

  -- 4. Validate customer belongs to company
  SELECT * INTO v_cust FROM public.customers
  WHERE company_id = p_company_id AND id = p_customer_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'RESOURCE_NOT_FOUND';
  END IF;

  -- 5. Validate order belongs to company and customer
  SELECT * INTO v_order FROM public.orders
  WHERE company_id = p_company_id AND customer_id = p_customer_id AND id = p_order_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'RESOURCE_NOT_FOUND';
  END IF;

  -- 6. Require order status COMPLETED
  IF v_order.order_status <> 'COMPLETED' THEN
    RAISE EXCEPTION 'INVALID_STATE_TRANSITION';
  END IF;

  -- 7. Validate or derive installation belonging strictly to this company, customer, and order
  IF p_installation_id IS NOT NULL THEN
    SELECT * INTO v_inst FROM public.installations
    WHERE company_id = p_company_id AND customer_id = p_customer_id AND order_id = p_order_id AND id = p_installation_id;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'RESOURCE_NOT_FOUND';
    END IF;
    v_derived_inst_id := v_inst.id;
  ELSE
    SELECT id INTO v_derived_inst_id FROM public.installations
    WHERE company_id = p_company_id AND customer_id = p_customer_id AND order_id = p_order_id
    ORDER BY created_at DESC LIMIT 1;
  END IF;

  -- 8. Insert warranty ticket
  INSERT INTO public.warranty_tickets (
    company_id,
    customer_id,
    order_id,
    installation_id,
    issue,
    status,
    assigned_to,
    notes,
    opened_at
  ) VALUES (
    p_company_id,
    p_customer_id,
    p_order_id,
    v_derived_inst_id,
    btrim(p_issue),
    'OPEN',
    NULL,
    p_notes,
    now()
  ) RETURNING * INTO v_ticket;

  -- 9. Insert audit log atomically in the same transaction
  INSERT INTO public.audit_logs (
    company_id,
    user_id,
    action,
    resource_type,
    resource_id,
    customer_id,
    result,
    metadata
  ) VALUES (
    p_company_id,
    p_actor_id,
    'CREATE_WARRANTY_TICKET',
    'warranty_tickets',
    v_ticket.id,
    p_customer_id,
    'SUCCESS',
    jsonb_build_object(
      'order_id', p_order_id,
      'installation_id', v_derived_inst_id,
      'idempotency_key', p_idempotency_key
    )
  );

  RETURN to_jsonb(v_ticket);
END;

DECLARE
  v_deleted_id uuid;
BEGIN
  PERFORM 1 FROM public.appointments WHERE id = p_appointment_id FOR UPDATE;
  DELETE FROM public.survey_photo_operations
  WHERE appointment_id = p_appointment_id AND token = p_token
  RETURNING appointment_id INTO v_deleted_id;

  IF v_deleted_id IS NULL THEN
    RAISE EXCEPTION 'SURVEY_PHOTO_GUARD_MISMATCH';
  END IF;
END

BEGIN
  IF NEW.customer_id IS DISTINCT FROM OLD.customer_id THEN
    RAISE EXCEPTION 'appointments.customer_id is immutable';
  END IF;
  IF NEW.type IS DISTINCT FROM OLD.type THEN
    IF EXISTS (SELECT 1 FROM public.surveys WHERE appointment_id = OLD.id)
       OR EXISTS (SELECT 1 FROM public.installations WHERE appointment_id = OLD.id) THEN
      RAISE EXCEPTION 'Cannot change appointment type when related survey or installation exists';
    END IF;
  END IF;
  RETURN NEW;
END;

BEGIN
  IF NEW.order_id IS DISTINCT FROM OLD.order_id THEN
    RAISE EXCEPTION 'contracts.order_id is immutable';
  END IF;
  IF OLD.signed_file_ref IS NOT NULL OR OLD.status = 'SIGNED' THEN
    IF NEW.contract_value IS DISTINCT FROM OLD.contract_value
       OR NEW.revision_no IS DISTINCT FROM OLD.revision_no
       OR NEW.template_version IS DISTINCT FROM OLD.template_version
       OR NEW.signed_at IS DISTINCT FROM OLD.signed_at
       OR NEW.generated_file_ref IS DISTINCT FROM OLD.generated_file_ref
       OR NEW.signed_file_ref IS DISTINCT FROM OLD.signed_file_ref THEN
      RAISE EXCEPTION 'Signed contract terms and file references are immutable';
    END IF;
  END IF;
  RETURN NEW;
END;

BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NOT EXISTS (
      SELECT 1 FROM public.appointments a
      WHERE a.id = NEW.appointment_id
        AND a.company_id = NEW.company_id
        AND a.customer_id = NEW.customer_id
        AND a.type = 'INSTALLATION'
    ) THEN
      RAISE EXCEPTION 'Installation appointment must be of type INSTALLATION and belong to the same company and customer';
    END IF;
  ELSIF TG_OP = 'UPDATE' THEN
    IF NEW.customer_id IS DISTINCT FROM OLD.customer_id
       OR NEW.order_id IS DISTINCT FROM OLD.order_id
       OR NEW.appointment_id IS DISTINCT FROM OLD.appointment_id THEN
      RAISE EXCEPTION 'installations customer_id, order_id, and appointment_id are immutable';
    END IF;
  END IF;
  RETURN NEW;
END;

BEGIN
  IF NEW.customer_id IS DISTINCT FROM OLD.customer_id
     OR NEW.order_code IS DISTINCT FROM OLD.order_code
     OR NEW.price_calculation_id IS DISTINCT FROM OLD.price_calculation_id THEN
    RAISE EXCEPTION 'orders customer_id, order_code, and price_calculation_id are immutable';
  END IF;
  RETURN NEW;
END;

BEGIN
  IF NEW.provider IS DISTINCT FROM OLD.provider
     OR NEW.provider_ref IS DISTINCT FROM OLD.provider_ref
     OR NEW.amount IS DISTINCT FROM OLD.amount
     OR NEW.occurred_at IS DISTINCT FROM OLD.occurred_at
     OR NEW.transfer_content IS DISTINCT FROM OLD.transfer_content THEN
    RAISE EXCEPTION 'payment_transactions provider source facts are immutable';
  END IF;
  RETURN NEW;
END;

BEGIN
  RAISE EXCEPTION 'price_calculations records are immutable snapshots and cannot be updated or deleted';
END;

BEGIN
  IF OLD.status = 'ACTIVE' THEN
    IF NEW.status = 'DRAFT' THEN
      RAISE EXCEPTION 'Active pricing policy cannot be reverted to DRAFT';
    END IF;
    IF NEW.version IS DISTINCT FROM OLD.version
       OR NEW.conditions IS DISTINCT FROM OLD.conditions
       OR NEW.price_rules IS DISTINCT FROM OLD.price_rules
       OR NEW.effective_at IS DISTINCT FROM OLD.effective_at THEN
      RAISE EXCEPTION 'Active pricing policy rules and version are immutable';
    END IF;
  END IF;
  RETURN NEW;
END;

BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NOT EXISTS (
      SELECT 1 FROM public.appointments a
      WHERE a.id = NEW.appointment_id
        AND a.company_id = NEW.company_id
        AND a.customer_id = NEW.customer_id
        AND a.type = 'SURVEY'
    ) THEN
      RAISE EXCEPTION 'Survey appointment must be of type SURVEY and belong to the same company and customer';
    END IF;
  ELSIF TG_OP = 'UPDATE' THEN
    IF NEW.customer_id IS DISTINCT FROM OLD.customer_id
       OR NEW.appointment_id IS DISTINCT FROM OLD.appointment_id
       OR NEW.completed_by IS DISTINCT FROM OLD.completed_by
       OR NEW.completed_at IS DISTINCT FROM OLD.completed_at THEN
      RAISE EXCEPTION 'Survey customer_id, appointment_id, completed_by, and completed_at are immutable';
    END IF;
  END IF;
  RETURN NEW;
END;

DECLARE
    v_contract public.contracts%ROWTYPE;
    v_order public.orders%ROWTYPE;
    v_expected_file_ref text;
    v_customer_previous_stage text;
BEGIN
    -- Section 13: Strict AAL2 enforcement (no fallback)
    IF p_aal_level <> 'aal2' THEN
        RAISE EXCEPTION 'AAL2_REQUIRED: Signing contracts requires AAL2 MFA authentication';
    END IF;

    -- Validate actor is ACTIVE BOSS_ADMIN in company
    IF NOT EXISTS (
        SELECT 1 FROM public.company_members cm
        JOIN public.user_profiles up ON cm.user_id = up.id
        WHERE cm.company_id = p_company_id
          AND cm.user_id = p_actor_user_id
          AND cm.status = 'ACTIVE'
          AND up.status = 'ACTIVE'
          AND cm.role = 'BOSS_ADMIN'
    ) THEN
        RAISE EXCEPTION 'UNAUTHORIZED_BOSS_REQUIRED';
    END IF;

    -- Lock Contract
    SELECT * INTO v_contract
    FROM public.contracts
    WHERE id = p_contract_id AND company_id = p_company_id
    FOR UPDATE;

    IF v_contract.id IS NULL THEN
        RAISE EXCEPTION 'RESOURCE_NOT_FOUND: Contract not found';
    END IF;

    -- Section 7: Contract must be current
    IF NOT v_contract.is_current THEN
        RAISE EXCEPTION 'INVALID_CONTRACT_STATE: Cannot sign non-current contract';
    END IF;

    -- Section 8: Validate canonical signed_file_ref against locked contract revision
    v_expected_file_ref := p_company_id::text || '/contracts/' || p_contract_id::text || '/revision-' || v_contract.revision_no::text || '/signed.pdf';
    IF p_signed_file_ref <> v_expected_file_ref THEN
        RAISE EXCEPTION 'INVALID_SIGNED_FILE_REF: Provided path does not match canonical contract pattern';
    END IF;

    -- Section 7: If already SIGNED, deterministic idempotency only if same file ref supplied
    IF v_contract.status = 'SIGNED' THEN
        IF v_contract.signed_file_ref = p_signed_file_ref THEN
            RETURN jsonb_build_object(
                'success', true,
                'status', 'ALREADY_PROCESSED',
                'contractId', p_contract_id,
                'orderId', v_contract.order_id
            );
        ELSE
            RAISE EXCEPTION 'CONTRACT_ALREADY_SIGNED_WITH_DIFFERENT_FILE: Cannot overwrite signed contract';
        END IF;
    END IF;

    -- Section 7: Allowed source states: only GENERATED or SENT_TO_CUSTOMER
    IF v_contract.status NOT IN ('GENERATED', 'SENT_TO_CUSTOMER') THEN
        RAISE EXCEPTION 'INVALID_CONTRACT_STATE: Cannot sign contract with status %', v_contract.status;
    END IF;

    -- Section 7: generated_file_ref must be valid and not 'CLAIMED'
    IF v_contract.generated_file_ref IS NULL OR v_contract.generated_file_ref = 'CLAIMED' THEN
        RAISE EXCEPTION 'CONTRACT_NOT_READY: Contract PDF has not been generated';
    END IF;

    -- Lock Order
    SELECT * INTO v_order
    FROM public.orders
    WHERE id = v_contract.order_id AND company_id = p_company_id
    FOR UPDATE;

    IF v_order.id IS NULL THEN
        RAISE EXCEPTION 'RESOURCE_NOT_FOUND: Order not found';
    END IF;

    -- Update contract
    UPDATE public.contracts
    SET 
        status = 'SIGNED',
        signed_at = now(),
        signed_file_ref = p_signed_file_ref,
        updated_at = now()
    WHERE id = p_contract_id;

    -- Update order to CONTRACT_SIGNED
    UPDATE public.orders
    SET 
        order_status = 'CONTRACT_SIGNED',
        updated_at = now()
    WHERE id = v_order.id;

    -- Section 3: Capture customer previous stage with row lock before updating
    SELECT stage INTO v_customer_previous_stage
    FROM public.customers
    WHERE id = v_order.customer_id AND company_id = p_company_id
    FOR UPDATE;

    -- Update customer stage to CONTRACT_SIGNED only if in earlier stage
    IF v_customer_previous_stage IN ('LEAD_NEW', 'LEAD', 'SURVEY_SCHEDULED', 'SURVEY_COMPLETED', 'PRICE_CALCULATED', 'PRICE_OFFERED', 'NEGOTIATING', 'ORDER_CREATED', 'DEPOSIT_CONFIRMED') THEN
        UPDATE public.customers
        SET stage = 'CONTRACT_SIGNED', updated_at = now()
        WHERE id = v_order.customer_id;

        INSERT INTO public.customer_stage_histories (
            company_id, customer_id, from_stage, to_stage, actor_type, changed_by_user_id, reason
        ) VALUES (
            p_company_id, v_order.customer_id, v_customer_previous_stage, 'CONTRACT_SIGNED', 'USER', p_actor_user_id, 'Contract signed by Boss Admin with AAL2'
        );
    END IF;

    -- Insert audit log
    INSERT INTO public.audit_logs (
        company_id, user_id, action, resource_type, resource_id, customer_id, result, metadata
    ) VALUES (
        p_company_id, p_actor_user_id, 'CONTRACT_SIGNED', 'contracts', p_contract_id, v_order.customer_id, 'SUCCESS',
        jsonb_build_object('signed_file_ref', p_signed_file_ref, 'order_id', v_order.id, 'signed_at', now())
    );

    RETURN jsonb_build_object('success', true, 'contractId', p_contract_id, 'orderId', v_order.id, 'status', 'SIGNED');
END;

DECLARE
    v_contract public.contracts%ROWTYPE;
    v_expected_file_ref text;
BEGIN
    SELECT * INTO v_contract
    FROM public.contracts
    WHERE id = p_contract_id AND company_id = p_company_id
    FOR UPDATE;

    IF v_contract.id IS NULL THEN
        RAISE EXCEPTION 'RESOURCE_NOT_FOUND: Contract not found';
    END IF;

    IF NOT v_contract.is_current THEN
        RAISE EXCEPTION 'INVALID_CONTRACT_STATE: Cannot finalize non-current contract';
    END IF;

    -- Section 8: Validate canonical generated file path against locked contract
    v_expected_file_ref := p_company_id::text || '/contracts/' || p_contract_id::text || '/revision-' || v_contract.revision_no::text || '/generated.pdf';
    IF p_generated_file_ref <> v_expected_file_ref THEN
        RAISE EXCEPTION 'INVALID_GENERATED_FILE_REF: Provided path does not match canonical contract pattern';
    END IF;

    UPDATE public.contracts
    SET 
        generated_file_ref = p_generated_file_ref,
        status = 'GENERATED',
        updated_at = now()
    WHERE id = p_contract_id;

    RETURN jsonb_build_object('success', true, 'contractId', p_contract_id, 'fileRef', p_generated_file_ref);
END;

BEGIN
  IF TG_OP = 'UPDATE' AND OLD.type = 'SURVEY' THEN
    IF OLD.status IN ('COMPLETED','CANCELLED','REJECTED') THEN
      IF NEW.status IS DISTINCT FROM OLD.status OR
         NEW.address IS DISTINCT FROM OLD.address OR
         NEW.assignee_id IS DISTINCT FROM OLD.assignee_id OR
         NEW.type IS DISTINCT FROM OLD.type THEN
        RAISE EXCEPTION 'SURVEY_APPOINTMENT_TERMINAL';
      END IF;
    END IF;
    -- A live (unexpired) photo operation blocks modifications
    IF EXISTS (
      SELECT 1 FROM public.survey_photo_operations
      WHERE appointment_id = OLD.id AND expires_at > pg_catalog.now()
    ) THEN
      RAISE EXCEPTION 'SURVEY_PHOTO_OPERATION_IN_PROGRESS';
    END IF;
    IF OLD.status <> 'COMPLETED' AND NEW.status = 'COMPLETED' THEN
      IF pg_catalog.current_setting('app.survey_completion', true) IS DISTINCT FROM NEW.id::text
         OR NOT EXISTS (SELECT 1 FROM public.surveys s WHERE s.appointment_id = NEW.id
           AND s.company_id = NEW.company_id AND s.customer_id = NEW.customer_id
           AND s.completed_by = NEW.assignee_id) THEN
        RAISE EXCEPTION 'SURVEY_COMPLETION_REQUIRES_ATOMIC_RPC';
      END IF;
    END IF;
  END IF;
  RETURN NEW;
END

DECLARE
  i public.installations;
  a public.appointments;
  r text;
  allowed jsonb := '{"SCHEDULED":["IN_TRANSIT","INSTALLING","FAILED"],"IN_TRANSIT":["INSTALLING","FAILED"],"INSTALLING":["TESTING","HANDOVER_PENDING","FAILED"],"TESTING":["HANDOVER_PENDING","INSTALLING","FAILED"],"HANDOVER_PENDING":["TESTING","INSTALLING","FAILED"],"FAILED":["SCHEDULED","IN_TRANSIT","INSTALLING"]}';
BEGIN
  r := public.operations_actor(p_company_id, p_actor_id, ARRAY['BOSS_ADMIN','TECHNICIAN']);
  SELECT * INTO i FROM public.installations WHERE company_id = p_company_id AND id = p_installation_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'RESOURCE_NOT_FOUND'; END IF;

  SELECT * INTO a FROM public.appointments WHERE company_id = p_company_id AND id = i.appointment_id FOR UPDATE;
  IF NOT FOUND OR a.customer_id <> i.customer_id OR a.type <> 'INSTALLATION' THEN RAISE EXCEPTION 'RESOURCE_NOT_FOUND'; END IF;

  IF r = 'TECHNICIAN' AND a.assignee_id <> p_actor_id THEN RAISE EXCEPTION 'PERMISSION_DENIED'; END IF;

  -- Require ACCEPTED or IN_PROGRESS appointment for both evidence upload and progress mutation.
  -- ASSIGNED appointment cannot upload evidence or mutate installation progress.
  IF i.status = 'COMPLETED' OR a.status NOT IN ('ACCEPTED', 'IN_PROGRESS') THEN
    RAISE EXCEPTION 'INVALID_STATE_TRANSITION';
  END IF;

  IF p_ref IS NOT NULL THEN
    IF NOT public.operations_evidence_ref(p_company_id, i.id, p_ref, p_type) THEN
      RAISE EXCEPTION 'INVALID_STORAGE_REF';
    END IF;
    UPDATE public.installations
    SET photos = CASE WHEN p_type = 'photo' AND NOT(photos ? p_ref) THEN photos || jsonb_build_array(p_ref) ELSE photos END,
        handover_ref = CASE WHEN p_type = 'handover' THEN p_ref ELSE handover_ref END,
        updated_at = now()
    WHERE id = i.id;
  ELSE
    IF NOT COALESCE((allowed->i.status) ? p_status, false) THEN
      RAISE EXCEPTION 'INVALID_STATE_TRANSITION';
    END IF;

    -- When appointment is ACCEPTED and field work mutates, promote appointment -> IN_PROGRESS
    IF a.status = 'ACCEPTED' THEN
      UPDATE public.appointments SET status = 'IN_PROGRESS', updated_at = now() WHERE id = a.id;
    END IF;

    -- If installation enters INSTALLING, advance order_status to INSTALLING if it was READY_FOR_INSTALL
    IF p_status = 'INSTALLING' THEN
      UPDATE public.orders SET order_status = 'INSTALLING', updated_at = now()
      WHERE company_id = p_company_id AND id = i.order_id AND order_status = 'READY_FOR_INSTALL';
    END IF;

    UPDATE public.installations SET status = p_status, updated_at = now() WHERE id = i.id;
  END IF;

  PERFORM public.operations_audit(
    p_company_id,
    p_actor_id,
    'UPDATE_INSTALLATION',
    'installations',
    i.id,
    jsonb_build_object('to_status', p_status, 'evidence_type', p_type)
  );
END;

DECLARE r text;
BEGIN
 SELECT m.role INTO r FROM public.company_members m JOIN public.user_profiles u ON u.id=m.user_id
 WHERE m.company_id=p_company AND m.user_id=p_actor AND m.status='ACTIVE' AND u.status='ACTIVE'
 FOR SHARE OF m,u;
 IF r IS NULL OR NOT(r=ANY(p_roles)) THEN RAISE EXCEPTION 'PERMISSION_DENIED'; END IF;
 RETURN r;
END

DECLARE
    v_company_id uuid;
    v_order public.orders%ROWTYPE;
    v_existing_tx public.payment_transactions%ROWTYPE;
    v_tx_id uuid;
    v_collected_amount numeric;
    v_required_deposit numeric;
    v_deposit_threshold_reached boolean := false;
    v_normalized_payment_ref text;
    v_payload_hash text;
    v_customer_previous_stage text;
BEGIN
    IF p_amount <= 0 THEN
        RAISE EXCEPTION 'AMOUNT_MUST_BE_POSITIVE';
    END IF;

    -- Canonicalize payment_reference (trim and uppercase, no reliance on arbitrary memo whitespace)
    v_normalized_payment_ref := UPPER(TRIM(COALESCE(p_payment_reference, '')));

    -- Strict company derivation from company_bank_accounts (no arbitrary tenant fallback)
    SELECT company_id INTO v_company_id
    FROM public.company_bank_accounts
    WHERE provider = p_provider AND provider_account = p_provider_account
    LIMIT 1;

    IF v_company_id IS NULL THEN
        RAISE EXCEPTION 'UNKNOWN_PROVIDER_ACCOUNT: % - %', p_provider, p_provider_account;
    END IF;

    -- Concurrency & Idempotency: Advisory lock per provider event reference
    -- Section 1: Lock scoped strictly to company_id + provider + provider_ref
    PERFORM pg_advisory_xact_lock(hashtext(v_company_id::text || ':PAYMENT:' || p_provider || ':' || p_provider_ref));

    -- Deterministic request fingerprint binding full logical payload
    v_payload_hash := encode(sha256(
        (v_company_id::text || '|' ||
         p_provider || '|' ||
         p_provider_account || '|' ||
         p_provider_ref || '|' ||
         p_amount::text || '|' ||
         v_normalized_payment_ref || '|' ||
         to_char(p_occurred_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"')
        )::bytea
    ), 'hex');

    -- Check if existing payment transaction exists for company_id, provider, and provider_ref
    SELECT * INTO v_existing_tx
    FROM public.payment_transactions
    WHERE company_id = v_company_id
      AND provider = p_provider
      AND provider_ref = p_provider_ref
    LIMIT 1;

    IF v_existing_tx.id IS NOT NULL THEN
        -- Section 1: Full logical payload duplicate validation
        -- Reject if amount, provider_account, payment_reference, company, or payload_hash changed
        IF v_existing_tx.company_id <> v_company_id
           OR v_existing_tx.provider_account <> p_provider_account
           OR v_existing_tx.amount <> p_amount
           OR COALESCE(v_existing_tx.payment_reference, '') <> v_normalized_payment_ref
           OR (v_existing_tx.payload_hash IS NOT NULL AND v_existing_tx.payload_hash <> v_payload_hash) THEN
            RAISE EXCEPTION 'PAYMENT_IDEMPOTENCY_KEY_REUSED_WITH_DIFFERENT_PAYLOAD';
        END IF;

        RETURN jsonb_build_object(
            'status', 'ALREADY_PROCESSED',
            'transactionId', v_existing_tx.id,
            'provider_ref', p_provider_ref,
            'orderId', v_existing_tx.matched_order_id
        );
    END IF;

    -- Look up Order by payment_reference strictly scoped to v_company_id
    SELECT * INTO v_order
    FROM public.orders
    WHERE payment_reference = v_normalized_payment_ref AND company_id = v_company_id
    FOR UPDATE;

    IF v_order.id IS NOT NULL THEN
        -- Insert matched transaction with logical fingerprint and payment reference
        INSERT INTO public.payment_transactions (
            company_id, provider, provider_account, provider_ref, amount, occurred_at, transfer_content,
            matched_order_id, match_confidence, status, payload_hash, payment_reference
        ) VALUES (
            v_company_id, p_provider, p_provider_account, p_provider_ref, p_amount, p_occurred_at, p_transfer_content,
            v_order.id, 1.0, 'MATCHED', v_payload_hash, v_normalized_payment_ref
        ) RETURNING id INTO v_tx_id;

        -- Update finance_summaries atomically
        INSERT INTO public.finance_summaries (order_id, company_id, contract_value, collected_amount, receivable_amount)
        VALUES (v_order.id, v_company_id, v_order.final_amount, p_amount, GREATEST(v_order.final_amount - p_amount, 0))
        ON CONFLICT (order_id) DO UPDATE 
        SET 
            collected_amount = public.finance_summaries.collected_amount + EXCLUDED.collected_amount,
            receivable_amount = GREATEST(public.finance_summaries.contract_value - (public.finance_summaries.collected_amount + EXCLUDED.collected_amount), 0),
            updated_at = now();

        -- Calculate cumulative collected amount
        SELECT collected_amount INTO v_collected_amount 
        FROM public.finance_summaries WHERE order_id = v_order.id;

        -- Retrieve required deposit from pricing policy conditions
        SELECT (pp.conditions->>'deposit_percentage')::numeric / 100 * v_order.final_amount
        INTO v_required_deposit
        FROM public.price_calculations pc
        JOIN public.pricing_policies pp ON pc.pricing_policy_id = pp.id
        WHERE pc.id = v_order.price_calculation_id;

        IF v_required_deposit IS NULL THEN
            RAISE EXCEPTION 'POLICY_CONFIGURATION_ERROR';
        END IF;

        IF v_collected_amount >= v_required_deposit THEN
            v_deposit_threshold_reached := true;
            UPDATE public.orders
            SET 
                deposit_status = 'DEPOSIT_CONFIRMED',
                order_status = 'DEPOSIT_CONFIRMED',
                updated_at = now()
            WHERE id = v_order.id;

            -- Capture customer previous stage with row lock before updating
            SELECT stage INTO v_customer_previous_stage
            FROM public.customers
            WHERE id = v_order.customer_id AND company_id = v_company_id
            FOR UPDATE;

            -- Update customer stage to DEPOSIT_CONFIRMED only if in earlier stage
            IF v_customer_previous_stage IN ('LEAD_NEW', 'LEAD', 'SURVEY_SCHEDULED', 'SURVEY_COMPLETED', 'PRICE_CALCULATED', 'PRICE_OFFERED', 'NEGOTIATING', 'ORDER_CREATED') THEN
                UPDATE public.customers
                SET stage = 'DEPOSIT_CONFIRMED', updated_at = now()
                WHERE id = v_order.customer_id;

                INSERT INTO public.customer_stage_histories (
                    company_id, customer_id, from_stage, to_stage, actor_type, changed_by_user_id, reason
                ) VALUES (
                    v_company_id, v_order.customer_id, v_customer_previous_stage, 'DEPOSIT_CONFIRMED', 'SYSTEM', NULL, 'Webhook deposit payment confirmed'
                );
            END IF;
        ELSE
            UPDATE public.orders
            SET deposit_status = 'DEPOSIT_PENDING', updated_at = now()
            WHERE id = v_order.id;
        END IF;

        RETURN jsonb_build_object(
            'status', 'MATCHED',
            'orderId', v_order.id,
            'transactionId', v_tx_id,
            'depositConfirmed', v_deposit_threshold_reached,
            'collectedAmount', v_collected_amount,
            'requiredDeposit', v_required_deposit
        );
    ELSE
        -- If order not found, insert as MANUAL_REVIEW_REQUIRED with 0 match confidence
        INSERT INTO public.payment_transactions (
            company_id, provider, provider_account, provider_ref, amount, occurred_at, transfer_content,
            matched_order_id, match_confidence, status, payload_hash, payment_reference
        ) VALUES (
            v_company_id, p_provider, p_provider_account, p_provider_ref, p_amount, p_occurred_at, p_transfer_content,
            NULL, 0, 'MANUAL_REVIEW_REQUIRED', v_payload_hash, v_normalized_payment_ref
        ) RETURNING id INTO v_tx_id;

        RETURN jsonb_build_object('status', 'MANUAL_REVIEW_REQUIRED', 'transactionId', v_tx_id);
    END IF;
END;

DECLARE
    v_calc_id uuid;
BEGIN
    -- Validate status & amount CHECK constraint invariant
    IF p_status = 'NEED_INFO' AND p_amount IS NOT NULL THEN
        RAISE EXCEPTION 'CHECK_VIOLATION: NEED_INFO must have NULL amount';
    END IF;
    IF p_status <> 'NEED_INFO' AND p_amount IS NULL THEN
        RAISE EXCEPTION 'CHECK_VIOLATION: CALCULATED status must have valid amount';
    END IF;

    -- Validate customer belongs to company
    IF NOT EXISTS (SELECT 1 FROM public.customers WHERE id = p_customer_id AND company_id = p_company_id) THEN
        RAISE EXCEPTION 'RESOURCE_NOT_FOUND: Customer does not belong to company';
    END IF;

    -- Validate survey if provided: must belong to same company and customer
    IF p_survey_id IS NOT NULL THEN
        IF NOT EXISTS (
            SELECT 1 FROM public.surveys
            WHERE id = p_survey_id AND company_id = p_company_id AND customer_id = p_customer_id
        ) THEN
            RAISE EXCEPTION 'RESOURCE_NOT_FOUND: Survey does not belong to company and customer';
        END IF;
    END IF;

    -- Validate pricing policy belongs to company, version matches, and is ACTIVE
    IF NOT EXISTS (
        SELECT 1 FROM public.pricing_policies 
        WHERE id = p_pricing_policy_id AND company_id = p_company_id AND version = p_policy_version AND status = 'ACTIVE'
    ) THEN
        RAISE EXCEPTION 'RESOURCE_NOT_FOUND: Active pricing policy not found or version mismatch';
    END IF;

    INSERT INTO public.price_calculations (
        company_id,
        customer_id,
        survey_id,
        pricing_policy_id,
        policy_version,
        input_data,
        amount,
        status,
        missing_fields
    ) VALUES (
        p_company_id,
        p_customer_id,
        p_survey_id,
        p_pricing_policy_id,
        p_policy_version,
        p_input_data,
        p_amount,
        p_status,
        COALESCE(p_missing_fields, '[]'::jsonb)
    ) RETURNING id INTO v_calc_id;

    RETURN jsonb_build_object('id', v_calc_id, 'status', p_status, 'amount', p_amount);
END;

DECLARE
  i public.installations;
  a public.appointments;
  r text;
BEGIN
  r := public.operations_actor(p_company_id, p_actor_id, ARRAY['TECHNICIAN']);

  SELECT * INTO i FROM public.installations
  WHERE company_id = p_company_id AND id = p_installation_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'RESOURCE_NOT_FOUND';
  END IF;

  SELECT * INTO a FROM public.appointments
  WHERE company_id = p_company_id AND id = i.appointment_id
  FOR UPDATE;

  IF NOT FOUND OR a.type <> 'INSTALLATION' THEN
    RAISE EXCEPTION 'RESOURCE_NOT_FOUND';
  END IF;

  IF a.assignee_id <> p_actor_id THEN
    RAISE EXCEPTION 'PERMISSION_DENIED';
  END IF;

  IF a.status = 'IN_PROGRESS' THEN
    RETURN jsonb_build_object('success', true, 'idempotent', true);
  END IF;

  IF a.status <> 'ACCEPTED' THEN
    RAISE EXCEPTION 'INVALID_STATE_TRANSITION';
  END IF;

  UPDATE public.appointments
  SET status = 'IN_PROGRESS',
      updated_at = now()
  WHERE id = a.id;

  PERFORM public.operations_audit(
    p_company_id,
    p_actor_id,
    'START_INSTALLATION_WORK',
    'appointments',
    a.id,
    jsonb_build_object('installation_id', i.id, 'from_status', 'ACCEPTED', 'to_status', 'IN_PROGRESS')
  );

  RETURN jsonb_build_object('success', true, 'idempotent', false);
END;

DECLARE
    v_order public.orders%ROWTYPE;
    v_existing_tx public.payment_transactions%ROWTYPE;
    v_tx_id uuid;
    v_collected_amount numeric;
    v_required_deposit numeric;
    v_deposit_threshold_reached boolean := false;
    v_payload_hash text;
    v_customer_previous_stage text;
BEGIN
    IF p_deposit_amount <= 0 THEN
        RAISE EXCEPTION 'Deposit amount must be greater than 0';
    END IF;

    -- Validate actor is BOSS_ADMIN in company
    IF NOT EXISTS (
        SELECT 1 FROM public.company_members cm
        JOIN public.user_profiles up ON cm.user_id = up.id
        WHERE cm.company_id = p_company_id
          AND cm.user_id = p_actor_user_id
          AND cm.status = 'ACTIVE'
          AND up.status = 'ACTIVE'
          AND cm.role = 'BOSS_ADMIN'
    ) THEN
        RAISE EXCEPTION 'UNAUTHORIZED_BOSS_REQUIRED';
    END IF;

    -- Concurrency: Advisory lock per (company_id, idempotency_key)
    PERFORM pg_advisory_xact_lock(hashtext(p_company_id::text || ':MANUAL:' || p_idempotency_key));

    -- Lock Order strictly scoped to company
    SELECT * INTO v_order
    FROM public.orders
    WHERE id = p_order_id AND company_id = p_company_id
    FOR UPDATE;

    IF v_order.id IS NULL THEN
        RAISE EXCEPTION 'RESOURCE_NOT_FOUND: Order not found';
    END IF;

    -- Check if idempotency key was already used
    SELECT * INTO v_existing_tx
    FROM public.payment_transactions
    WHERE company_id = p_company_id AND provider = 'MANUAL' AND provider_ref = p_idempotency_key;

    IF v_existing_tx.id IS NOT NULL THEN
        -- Section 2: Idempotency must strictly bind to matched_order_id and amount
        IF v_existing_tx.matched_order_id IS DISTINCT FROM p_order_id OR v_existing_tx.amount <> p_deposit_amount THEN
            RAISE EXCEPTION 'PAYMENT_IDEMPOTENCY_KEY_REUSED_WITH_DIFFERENT_PAYLOAD';
        END IF;

        SELECT collected_amount INTO v_collected_amount 
        FROM public.finance_summaries WHERE order_id = p_order_id;

        SELECT (pp.conditions->>'deposit_percentage')::numeric / 100 * v_order.final_amount
        INTO v_required_deposit
        FROM public.price_calculations pc
        JOIN public.pricing_policies pp ON pc.pricing_policy_id = pp.id
        WHERE pc.id = v_order.price_calculation_id;

        RETURN jsonb_build_object(
            'success', true,
            'status', 'ALREADY_PROCESSED',
            'orderId', v_existing_tx.matched_order_id,
            'transactionId', v_existing_tx.id,
            'depositConfirmed', (v_order.deposit_status IN ('CONFIRMED', 'DEPOSIT_CONFIRMED')),
            'collectedAmount', COALESCE(v_collected_amount, 0),
            'requiredDeposit', v_required_deposit
        );
    END IF;

    -- Compute deterministic payload hash for manual transaction
    v_payload_hash := encode(sha256(
        (p_company_id::text || ':MANUAL:' || p_idempotency_key || ':' || p_order_id::text || ':' || p_deposit_amount::text)::bytea
    ), 'hex');

    -- Insert manual transaction
    INSERT INTO public.payment_transactions (
        company_id, provider, provider_account, provider_ref, amount, occurred_at, transfer_content,
        matched_order_id, match_confidence, status, payload_hash, payment_reference
    ) VALUES (
        p_company_id, 'MANUAL', 'MANUAL_CASH', p_idempotency_key, p_deposit_amount, now(), 'MANUAL DEPOSIT CONFIRMATION',
        v_order.id, 1.0, 'MATCHED', v_payload_hash, v_order.payment_reference
    ) RETURNING id INTO v_tx_id;

    -- Update finance_summaries
    INSERT INTO public.finance_summaries (order_id, company_id, contract_value, collected_amount, receivable_amount)
    VALUES (v_order.id, p_company_id, v_order.final_amount, p_deposit_amount, GREATEST(v_order.final_amount - p_deposit_amount, 0))
    ON CONFLICT (order_id) DO UPDATE 
    SET 
        collected_amount = public.finance_summaries.collected_amount + EXCLUDED.collected_amount,
        receivable_amount = GREATEST(public.finance_summaries.contract_value - (public.finance_summaries.collected_amount + EXCLUDED.collected_amount), 0),
        updated_at = now();

    SELECT collected_amount INTO v_collected_amount 
    FROM public.finance_summaries WHERE order_id = p_order_id;

    SELECT (pp.conditions->>'deposit_percentage')::numeric / 100 * v_order.final_amount
    INTO v_required_deposit
    FROM public.price_calculations pc
    JOIN public.pricing_policies pp ON pc.pricing_policy_id = pp.id
    WHERE pc.id = v_order.price_calculation_id;

    IF v_required_deposit IS NULL THEN
        RAISE EXCEPTION 'POLICY_CONFIGURATION_ERROR';
    END IF;

    IF v_collected_amount >= v_required_deposit THEN
        v_deposit_threshold_reached := true;
        UPDATE public.orders
        SET 
            deposit_status = 'DEPOSIT_CONFIRMED',
            order_status = 'DEPOSIT_CONFIRMED',
            updated_at = now()
        WHERE id = p_order_id;

        -- Capture customer previous stage with row lock before updating
        SELECT stage INTO v_customer_previous_stage
        FROM public.customers
        WHERE id = v_order.customer_id AND company_id = p_company_id
        FOR UPDATE;

        -- Update customer stage to DEPOSIT_CONFIRMED only if in earlier stage
        IF v_customer_previous_stage IN ('LEAD_NEW', 'LEAD', 'SURVEY_SCHEDULED', 'SURVEY_COMPLETED', 'PRICE_CALCULATED', 'PRICE_OFFERED', 'NEGOTIATING', 'ORDER_CREATED') THEN
            UPDATE public.customers
            SET stage = 'DEPOSIT_CONFIRMED', updated_at = now()
            WHERE id = v_order.customer_id;

            INSERT INTO public.customer_stage_histories (
                company_id, customer_id, from_stage, to_stage, actor_type, changed_by_user_id, reason
            ) VALUES (
                p_company_id, v_order.customer_id, v_customer_previous_stage, 'DEPOSIT_CONFIRMED', 'USER', p_actor_user_id, 'Manual deposit confirmed by Boss Admin'
            );
        END IF;
    ELSE
        UPDATE public.orders
        SET deposit_status = 'DEPOSIT_PENDING', updated_at = now()
        WHERE id = p_order_id;
    END IF;

    -- Mandatory audit log
    INSERT INTO public.audit_logs (company_id, user_id, action, resource_type, resource_id, customer_id, result, metadata)
    VALUES (
        p_company_id, p_actor_user_id, 'MANUAL_DEPOSIT_CONFIRMED', 'orders', p_order_id, v_order.customer_id, 'SUCCESS',
        jsonb_build_object('amount', p_deposit_amount, 'collected_amount', v_collected_amount, 'required_deposit', v_required_deposit)
    );

    RETURN jsonb_build_object(
        'success', true,
        'status', 'MATCHED',
        'orderId', p_order_id,
        'transactionId', v_tx_id,
        'depositConfirmed', v_deposit_threshold_reached,
        'collectedAmount', v_collected_amount,
        'requiredDeposit', v_required_deposit
    );
END;

DECLARE p public.production_orders;
BEGIN
 PERFORM public.operations_actor(p_company_id,p_actor_id,ARRAY['BOSS_ADMIN']);
 SELECT * INTO p FROM public.production_orders WHERE company_id=p_company_id AND id=p_production_order_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'RESOURCE_NOT_FOUND'; END IF;
 IF p_status IS NULL OR p_status NOT IN ('RELEASED_TO_FACTORY','IN_PRODUCTION','QC_IN_PROGRESS') OR NOT (
 (p.status='PENDING_SPECS' AND p_status='RELEASED_TO_FACTORY') OR
 (p.status IN ('RELEASED_TO_FACTORY','QC_IN_PROGRESS','QC_FAILED','READY_FOR_DISPATCH') AND p_status='IN_PRODUCTION') OR
 (p.status='IN_PRODUCTION' AND p_status='QC_IN_PROGRESS')) THEN RAISE EXCEPTION 'INVALID_STATE_TRANSITION'; END IF;
 UPDATE public.production_orders SET status=p_status,qc_status=CASE WHEN p_status='IN_PRODUCTION' THEN 'PENDING' ELSE qc_status END,updated_at=now() WHERE id=p.id;
 PERFORM public.operations_audit(p_company_id,p_actor_id,'UPDATE_PRODUCTION_PROGRESS','production_orders',p.id,jsonb_build_object('from_status',p.status,'to_status',p_status));
END

DECLARE t public.warranty_tickets; r text; next_status text; allowed jsonb := '{"OPEN":["CANCELLED"],"ASSIGNED":["IN_PROGRESS","OPEN","CANCELLED"],"IN_PROGRESS":["RESOLVED","FAILED"],"RESOLVED":["CLOSED"],"REOPENED":["IN_PROGRESS"]}';
BEGIN
 r := public.operations_actor(p_company_id,p_actor_id,ARRAY['BOSS_ADMIN','TECHNICIAN','SALE']);
 IF r IS DISTINCT FROM p_actor_role THEN RAISE EXCEPTION 'PERMISSION_DENIED'; END IF;
 SELECT * INTO t FROM public.warranty_tickets WHERE company_id=p_company_id AND id=p_ticket_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'RESOURCE_NOT_FOUND'; END IF;
 IF r='TECHNICIAN' AND t.assigned_to IS DISTINCT FROM p_actor_id THEN RAISE EXCEPTION 'PERMISSION_DENIED'; END IF;
 IF p_operation='assign' THEN
  IF r<>'BOSS_ADMIN' THEN RAISE EXCEPTION 'PERMISSION_DENIED'; END IF;
  IF t.status NOT IN ('OPEN','REOPENED','ASSIGNED') THEN RAISE EXCEPTION 'INVALID_STATE_TRANSITION'; END IF;
  PERFORM public.operations_actor(p_company_id,p_technician_id,ARRAY['TECHNICIAN']);
  next_status := 'ASSIGNED';
 ELSIF p_operation='reopen' THEN
  IF r NOT IN ('BOSS_ADMIN','SALE') THEN RAISE EXCEPTION 'PERMISSION_DENIED'; END IF;
  IF t.status NOT IN ('RESOLVED','CLOSED') OR NULLIF(btrim(p_notes),'') IS NULL THEN RAISE EXCEPTION 'INVALID_STATE_TRANSITION'; END IF;
  next_status := 'REOPENED';
 ELSIF p_operation='update' THEN
  IF r NOT IN ('BOSS_ADMIN','TECHNICIAN') THEN RAISE EXCEPTION 'PERMISSION_DENIED'; END IF;
  IF NOT COALESCE((allowed->t.status) ? p_status,false) THEN RAISE EXCEPTION 'INVALID_STATE_TRANSITION'; END IF;
  next_status := p_status;
 ELSE RAISE EXCEPTION 'INVALID_INPUT'; END IF;
 UPDATE public.warranty_tickets SET status=next_status,
 assigned_to=CASE WHEN p_operation='assign' THEN p_technician_id WHEN next_status='OPEN' THEN NULL ELSE assigned_to END,
 resolved_at=CASE WHEN next_status='RESOLVED' THEN now() WHEN next_status='REOPENED' THEN NULL ELSE resolved_at END,
 notes=CASE WHEN p_operation='reopen' THEN concat_ws(E'\n',notes,'REOPEN: '||p_notes) ELSE COALESCE(p_notes,notes) END,updated_at=now() WHERE id=t.id;
 PERFORM public.operations_audit(p_company_id,p_actor_id,'WARRANTY_'||upper(p_operation),'warranty_tickets',t.id,jsonb_build_object('from_status',t.status,'to_status',next_status));
END
